bopomofo.css:
.card {
  text-align: center;
  font-size: 17px;
  line-height: 1.6;
}
.uc-ask {
  margin-bottom: 14px;
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.55;
}
.uc-pinyin {
  font-family: 'EB Garamond', var(--serif, Georgia, serif);
  margin-top: 12px;
  font-size: 21px;
  letter-spacing: 0.01em;
  color: var(--zh, #C8453C);
}
.uc-field {
  display: block;
  width: fit-content;
  max-width: 100%;
  margin: 14px auto 0;
  padding: 11px 15px;
  border: 1px solid var(--rule, rgba(0,0,0,0.12));
  border-radius: 11px;
  text-align: left;
  font-size: 16px;
  background: var(--paper-2, rgba(0,0,0,0.05));
  background: color-mix(in srgb, var(--paper-2, #EFEDE6) 58%, var(--card, #FFFFFF));
}
.uc-tts {
  background: var(--paper, #F6F5F1);
  border-color: var(--paper-2, rgba(0,0,0,0.12));
}
.uc-exsay {
  margin-right: 7px;
  font-size: 12px;
  vertical-align: 0.08em;
}
.uc-lab {
  display: block;
  margin-bottom: 5px;
  font-size: 9.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.5;
}
.uc-rows {
  display: block;
  width: fit-content;
  max-width: 100%;
  margin: 14px auto 0;
  padding-top: 10px;
  border-top: 1px solid var(--rule, rgba(0,0,0,0.10));
  text-align: left;
}
.uc-row {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 3px 0;
  font-size: 13.5px;
}
.uc-row + .uc-row {
  border-top: 1px solid var(--rule, rgba(0,0,0,0.10));
}
.uc-rz {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-weight: 400;
  font-size: 18px;
  line-height: 1.25;
  min-width: 3.2em;
  white-space: nowrap;
}
.uc-rp {
  font-family: 'EB Garamond', var(--serif, Georgia, serif);
  font-size: 15px;
  min-width: 5.4em;
  opacity: 0.8;
}
.uc-rp b {
  font-weight: 400;
  color: var(--zh, #C8453C);
}
.uc-rg {
  flex: 1 1 auto;
  opacity: 0.85;
}
.uc-rs {
  display: block;
  font-size: 12px;
  opacity: 0.7;
}
hr {
  margin: 18px 0;
  border: 0;
  border-top: 1px solid currentColor;
  opacity: 0.18;
}
.uc-bpmf {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-size: 58px;
  font-weight: 400;
  line-height: 1.15;
}
.uc-cls {
  margin-top: 4px;
  font-family: 'EB Garamond', var(--serif, Georgia, serif);
  font-size: 17px;
  opacity: 0.75;
}
.uc-note {
  max-width: 30em;
  margin: 10px auto 0;
  font-size: 13.5px;
  opacity: 0.8;
}
.uc-rb {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-size: 15px;
  min-width: 6em;
}
.uc-rb b {
  font-weight: 400;
  color: var(--zh, #C8453C);
}
.uc-rb .uc-rs {
  font-family: 'EB Garamond', var(--serif, Georgia, serif);
}
